import java.util.Stack;

public class ExpressionChecker {
    public static boolean checkExpression(String exp) {
        if (exp.length() % 2 != 0) {
            return false;
        }
        Stack<Character> stack = new Stack<>();
        for (char ch : exp.toCharArray()) {
            if (ch == '(' || ch == '{' || ch == '[') {
                stack.push(ch);
            }
            if (ch == ')' || ch == '}' || ch == ']') {
                if (stack.isEmpty()) {
                    return false;
                }
                char top = stack.pop();
                if ((top == '(' && ch != ')') ||
                    (top == '{' && ch != '}') ||
                    (top == '[' && ch != ']')) {
                    return false;
                }
            }
        }
        return stack.isEmpty();
    }
}

public class Solution {
    public static int[] rightRotate(int[] arr, int outOfPlace, int cur) {
        int temp = arr[cur];
        for (int i = cur; i > outOfPlace; i--) {
            arr[i] = arr[i - 1];
        }
        arr[outOfPlace] = temp;
        return arr;
    }

    public static int[] reArrange(int[] arr) {
        int n = arr.length;
        int outOfPlace = -1;
        for (int index = 0; index < n; index++) {
            if (outOfPlace >= 0) {
                if ((arr[index] >= 0 && arr[outOfPlace] < 0) ||
                    (arr[index] < 0 && arr[outOfPlace] >= 0)) {
                    arr = rightRotate(arr, outOfPlace, index);
                    if (index - outOfPlace > 2) {
                        outOfPlace += 2;
                    } else {
                        outOfPlace = -1;
                    }
                }
            }
            if (outOfPlace == -1) {
                if ((arr[index] >= 0 && index % 2 == 0) ||
                    (arr[index] < 0 && index % 2 == 1)) {
                    outOfPlace = index;
                }
            }
        }
        return arr;
    }
}

public class Solution {
    public static int firstMissingPositive(int[] arr) {
        int n = arr.length;
        boolean hasOne = false;
        for (int i = 0; i < n; i++) {
            if (arr[i] == 1) {
                hasOne = true;
                break;
            }
        }
        if (!hasOne) {
            return 1;
        }
        for (int i = 0; i < n; i++) {
            if (arr[i] <= 0 || arr[i] > n) {
                arr[i] = 1;
            }
        }
        for (int i = 0; i < n; i++) {
            int index = (arr[i] - 1) % n;
            arr[index] += n;
        }
        for (int i = 0; i < n; i++) {
            if (arr[i] <= n) {
                return i + 1;
            }
        }
        return n + 1;
    }
}

import java.util.Arrays;

public class Solution {
    public static int lbs(int[] arr) {
        int n = arr.length;
        int[] lis = new int[n];
        Arrays.fill(lis, 1);
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (arr[i] > arr[j] && lis[i] < lis[j] + 1) {
                    lis[i] = lis[j] + 1;
                }
            }
        }
        int[] lds = new int[n];
        Arrays.fill(lds, 1);
        for (int i = n - 2; i >= 0; i--) {
            for (int j = n - 1; j > i; j--) {
                if (arr[i] > arr[j] && lds[i] < lds[j] + 1) {
                    lds[i] = lds[j] + 1;
                }
            }
        }
        int max = lis[0] + lds[0] - 1;
        for (int i = 1; i < n; i++) {
            max = Math.max(max, lis[i] + lds[i] - 1);
        }
        return max;
    }
}

public class Solution {
    public static int maxSum(int[] arr, int n) {
        int[] MSIBS = arr.clone();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++) {
                if (arr[i] > arr[j] && MSIBS[i] < MSIBS[j] + arr[i]) {
                    MSIBS[i] = MSIBS[j] + arr[i];
                }
            }
        }
        int[] MSDBS = arr.clone();
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j < i; j++) {
                int idxI = n - i;
                int idxJ = n - j;
                if (arr[idxI] > arr[idxJ] && MSDBS[idxI] < MSDBS[idxJ] + arr[idxI]) {
                    MSDBS[idxI] = MSDBS[idxJ] + arr[idxI];
                }
            }
        }
        int maxSum = Integer.MIN_VALUE;
        for (int k = 0; k < n; k++) {
            maxSum = Math.max(maxSum, MSIBS[k] + MSDBS[k] - arr[k]);
        }
        return maxSum;
    }
}

public class Solution {
    public static int countVowels(String testStr) {
        int res = 0;
        String vowels = "aeiou";
        int n = testStr.length();
        for (int i = 1; i < n - 1; i++) {
            char c = testStr.charAt(i);
            if (vowels.indexOf(c) == -1) {
                char prev = testStr.charAt(i - 1);
                char next = testStr.charAt(i + 1);
                if (vowels.indexOf(prev) != -1 || vowels.indexOf(next) != -1) {
                    res++;
                }
            }
        }
        if (n > 1) {
            if (vowels.indexOf(testStr.charAt(0)) == -1 && vowels.indexOf(testStr.charAt(1)) != -1) {
                res++;
            }
            if (vowels.indexOf(testStr.charAt(n - 1)) == -1 && vowels.indexOf(testStr.charAt(n - 2)) != -1) {
                res++;
            }
        }
        return res;
    }
}

import java.util.*;

public class Solution {
    public String rearangeString(String S) {
        Map<Character, Integer> count = new HashMap<>();
        for (char c : S.toCharArray()) {
            count.put(c, count.getOrDefault(c, 0) + 1);
        }
        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> b.count - a.count);
        for (Map.Entry<Character, Integer> entry : count.entrySet()) {
            pq.offer(new Node(entry.getKey(), entry.getValue()));
        }
        if (!pq.isEmpty() && pq.peek().count * 2 > S.length() + 1) {
            return "";
        }
        StringBuilder ans = new StringBuilder();
        while (pq.size() >= 2) {
            Node n1 = pq.poll();
            Node n2 = pq.poll();
            ans.append(n1.ch).append(n2.ch);
            if (--n1.count > 0) {
                pq.offer(n1);
            }
            if (--n2.count > 0) {
                pq.offer(n2);
            }
        }
        if (!pq.isEmpty()) {
            ans.append(pq.poll().ch);
        }
        return ans.toString();
    }

    private static class Node {
        char ch;
        int count;
        Node(char ch, int count) {
            this.ch = ch;
            this.count = count;
        }
    }
}

