public class AmicableNumbers {
    public static int amicableNumbersSum(int limit) {
        if (limit < 1) {
            throw new IllegalArgumentException("Input must be bigger than 0!");
        }
        Set<Integer> amicables = new HashSet<>();
        for (int num = 2; num <= limit; num++) {
            if (amicables.contains(num)) {
                continue;
            }
            int sumFact = sumOfDivisors(num);
            int sumFact2 = sumOfDivisors(sumFact);
            if (num == sumFact2 && num != sumFact) {
                amicables.add(num);
                amicables.add(sumFact2);
            }
        }
        int total = 0;
        for (int n : amicables) {
            total += n;
        }
        return total;
    }

    private static int sumOfDivisors(int n) {
        int sum = 0;
        for (int i = 1; i < n; i++) {
            if (n % i == 0) {
                sum += i;
            }
        }
        return sum;
    }
}

public class Solution {
    public static boolean modularSum(int[] arr, int n, int m) {
        if (n > m) {
            return true;
        }
        boolean[] DP = new boolean[m];
        for (int i = 0; i < n; i++) {
            if (DP[0]) {
                return true;
            }
            boolean[] temp = new boolean[m];
            for (int j = 0; j < m; j++) {
                if (DP[j]) {
                    int idx = (j + arr[i]) % m;
                    if (!DP[idx]) {
                        temp[idx] = true;
                    }
                }
            }
            for (int j = 0; j < m; j++) {
                if (temp[j]) {
                    DP[j] = true;
                }
            }
            DP[arr[i] % m] = true;
        }
        return DP[0];
    }
}

public class Solution {
    public static boolean isMajority(int[] arr, int n, int x) {
        int i = binarySearch(arr, 0, n - 1, x);
        if (i == -1) {
            return false;
        }
        if (i + n / 2 <= n - 1 && arr[i + n / 2] == x) {
            return true;
        } else {
            return false;
        }
    }

    public static int binarySearch(int[] arr, int low, int high, int x) {
        if (high >= low) {
            int mid = (low + high) / 2;
            if ((mid == 0 || x > arr[mid - 1]) && arr[mid] == x) {
                return mid;
            } else if (x > arr[mid]) {
                return binarySearch(arr, mid + 1, high, x);
            } else {
                return binarySearch(arr, low, mid - 1, x);
            }
        }
        return -1;
    }
}

