public class SublistChecker {
    public static <T> boolean isSublist(List<T> l, List<T> s) {
        if (s.isEmpty()) {
            return true;
        } else if (s.equals(l)) {
            return true;
        } else if (s.size() > l.size()) {
            return false;
        } else {
            for (int i = 0; i <= l.size() - s.size(); i++) {
                if (l.get(i).equals(s.get(0))) {
                    int n = 1;
                    while (n < s.size() && l.get(i + n).equals(s.get(n))) {
                        n++;
                    }
                    if (n == s.size()) {
                        return true;
                    }
                }
            }
            return false;
        }
    }
}

public class LCS3 {
    public static int lcsOfThree(String X, String Y, String Z) {
        int m = X.length();
        int n = Y.length();
        int o = Z.length();
        int[][][] L = new int[m + 1][n + 1][o + 1];
        for (int i = 0; i <= m; i++) {
            for (int j = 0; j <= n; j++) {
                for (int k = 0; k <= o; k++) {
                    if (i == 0 || j == 0 || k == 0) {
                        L[i][j][k] = 0;
                    } else if (X.charAt(i - 1) == Y.charAt(j - 1) && X.charAt(i - 1) == Z.charAt(k - 1)) {
                        L[i][j][k] = L[i - 1][j - 1][k - 1] + 1;
                    } else {
                        L[i][j][k] = Math.max(
                            Math.max(L[i - 1][j][k], L[i][j - 1][k]),
                            L[i][j][k - 1]
                        );
                    }
                }
            }
        }
        return L[m][n][o];
    }
}

