public class Solution {
    public List<List<Integer>> kSmallestPairs(int[] nums1, int[] nums2, int k) {
        List<List<Integer>> pairs = new ArrayList<>();
        if (nums1.length == 0 || nums2.length == 0 || k <= 0) {
            return pairs;
        }
        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[]{nums1[0] + nums2[0], 0, 0});
        while (!pq.isEmpty() && pairs.size() < k) {
            int[] curr = pq.poll();
            int i = curr[1], j = curr[2];
            pairs.add(Arrays.asList(nums1[i], nums2[j]));
            if (j + 1 < nums2.length) {
                pq.offer(new int[]{nums1[i] + nums2[j + 1], i, j + 1});
            }
            if (j == 0 && i + 1 < nums1.length) {
                pq.offer(new int[]{nums1[i + 1] + nums2[j], i + 1, j});
            }
        }
        return pairs;
    }
}

public class Solution {
    public static int minSwaps(String s1, String s2) {
        int c0 = 0;
        int c1 = 0;
        for (int i = 0; i < s1.length(); i++) {
            char a = s1.charAt(i);
            char b = s2.charAt(i);
            if (a == '0' && b == '1') {
                c0++;
            } else if (a == '1' && b == '0') {
                c1++;
            }
        }
        int result = c0 / 2 + c1 / 2;
        if (c0 % 2 == 0 && c1 % 2 == 0) {
            return result;
        } else if ((c0 + c1) % 2 == 0) {
            return result + 2;
        } else {
            return -1;
        }
    }
}

public class GoldMine {
    public static int getMaxGold(int[][] gold, int m, int n) {
        int[][] goldTable = new int[m][n];
        for (int col = n - 1; col >= 0; col--) {
            for (int row = 0; row < m; row++) {
                int right = (col == n - 1) ? 0 : goldTable[row][col + 1];
                int rightUp = (row == 0 || col == n - 1) ? 0 : goldTable[row - 1][col + 1];
                int rightDown = (row == m - 1 || col == n - 1) ? 0 : goldTable[row + 1][col + 1];
                goldTable[row][col] = gold[row][col] + Math.max(Math.max(right, rightUp), rightDown);
            }
        }
        int res = goldTable[0][0];
        for (int i = 1; i < m; i++) {
            res = Math.max(res, goldTable[i][0]);
        }
        return res;
    }
}

