public class HeapSort {
    public static int[] heapSort(int[] arr) {
        heapify(arr);
        int end = arr.length - 1;
        while (end > 0) {
            int temp = arr[end];
            arr[end] = arr[0];
            arr[0] = temp;
            shiftDown(arr, 0, end - 1);
            end--;
        }
        return arr;
    }

    private static void heapify(int[] arr) {
        int start = arr.length / 2;
        while (start >= 0) {
            shiftDown(arr, start, arr.length - 1);
            start--;
        }
    }

    private static void shiftDown(int[] arr, int start, int end) {
        int root = start;
        while (root * 2 + 1 <= end) {
            int child = root * 2 + 1;
            if (child + 1 <= end && arr[child] < arr[child + 1]) {
                child++;
            }
            if (child <= end && arr[root] < arr[child]) {
                int temp = arr[root];
                arr[root] = arr[child];
                arr[child] = temp;
                root = child;
            } else {
                return;
            }
        }
    }
}

public class Solution {
    public static String replaceSpaces(String s) {
        final int MAX = 1000;
        s = s.trim();
        int i = s.length();
        int spaceCount = 0;
        for (int k = 0; k < i; k++) {
            if (s.charAt(k) == ' ') {
                spaceCount++;
            }
        }
        int newLength = i + spaceCount * 2;
        if (newLength > MAX) {
            return "-1";
        }
        char[] chars = new char[newLength];
        for (int k = 0; k < i; k++) {
            chars[k] = s.charAt(k);
        }
        for (int f = i; f < newLength; f++) {
            chars[f] = '0';
        }
        int index = newLength - 1;
        for (int j = i - 1; j > 0; j--) {
            if (chars[j] == ' ') {
                chars[index] = '0';
                chars[index - 1] = '2';
                chars[index - 2] = '%';
                index -= 3;
            } else {
                chars[index] = chars[j];
                index--;
            }
        }
        return new String(chars);
    }
}

public class Solution {
    public static String findMaxLenEven(String str) {
        int n = str.length();
        int i = 0;
        int currlen = 0;
        int maxlen = 0;
        int st = -1;
        while (i < n) {
            if (str.charAt(i) == ' ') {
                if (currlen % 2 == 0) {
                    if (maxlen < currlen) {
                        maxlen = currlen;
                        st = i - currlen;
                    }
                }
                currlen = 0;
            } else {
                currlen++;
            }
            i++;
        }
        if (currlen % 2 == 0) {
            if (maxlen < currlen) {
                maxlen = currlen;
                st = i - currlen;
            }
        }
        if (st == -1) {
            return "-1";
        }
        return str.substring(st, st + maxlen);
    }
}

