public class RadixSort {
    public static int[] radixSort(int[] nums) {
        final int RADIX = 10;
        int placement = 1;
        int maxDigit = nums[0];
        for (int num : nums) {
            if (num > maxDigit) {
                maxDigit = num;
            }
        }
        while (placement < maxDigit) {
            @SuppressWarnings("unchecked")
            List<Integer>[] buckets = new ArrayList[RADIX];
            for (int i = 0; i < RADIX; i++) {
                buckets[i] = new ArrayList<>();
            }
            for (int i : nums) {
                int tmp = (i / placement) % RADIX;
                buckets[tmp].add(i);
            }
            int a = 0;
            for (int b = 0; b < RADIX; b++) {
                for (int value : buckets[b]) {
                    nums[a++] = value;
                }
            }
            placement *= RADIX;
        }
        return nums;
    }
}

public class Solution {
    public static int[][] generateMatrix(int n) {
        if (n <= 0) {
            return new int[0][0];
        }
        int[][] matrix = new int[n][n];
        int rowStart = 0, rowEnd = n - 1;
        int colStart = 0, colEnd = n - 1;
        int current = 1;
        while (true) {
            if (current > n * n) {
                break;
            }
            for (int c = colStart; c <= colEnd; c++) {
                matrix[rowStart][c] = current++;
            }
            rowStart++;
            for (int r = rowStart; r <= rowEnd; r++) {
                matrix[r][colEnd] = current++;
            }
            colEnd--;
            for (int c = colEnd; c >= colStart; c--) {
                matrix[rowEnd][c] = current++;
            }
            rowEnd--;
            for (int r = rowEnd; r >= rowStart; r--) {
                matrix[r][colStart] = current++;
            }
            colStart++;
        }
        return matrix;
    }
}

public class MergeSort {
    public static int[] merge(int[] a, int[] b) {
        int[] c = new int[a.length + b.length];
        int i = 0, j = 0, k = 0;
        while (i < a.length && j < b.length) {
            if (a[i] < b[j]) {
                c[k++] = a[i++];
            } else {
                c[k++] = b[j++];
            }
        }
        while (i < a.length) {
            c[k++] = a[i++];
        }
        while (j < b.length) {
            c[k++] = b[j++];
        }
        return c;
    }

    public static int[] mergeSort(int[] x) {
        if (x == null || x.length <= 1) {
            return x;
        }
        int middle = x.length / 2;
        int[] left = new int[middle];
        System.arraycopy(x, 0, left, 0, middle);
        int[] right = new int[x.length - middle];
        System.arraycopy(x, middle, right, 0, x.length - middle);
        return merge(mergeSort(left), mergeSort(right));
    }
}

