public class SecondSmallestFinder {
    public static Integer secondSmallest(List<Integer> numbers) {
        if (numbers == null || numbers.size() < 2) {
            return null;
        }
        if (numbers.size() == 2 && numbers.get(0).equals(numbers.get(1))) {
            return null;
        }
        Set<Integer> dupItems = new HashSet<>();
        List<Integer> uniqItems = new ArrayList<>();
        for (Integer x : numbers) {
            if (!dupItems.contains(x)) {
                uniqItems.add(x);
                dupItems.add(x);
            }
        }
        Collections.sort(uniqItems);
        return uniqItems.size() >= 2 ? uniqItems.get(1) : null;
    }
}

public class Rencontres {
    public static long binomialCoeff(int n, int k) {
        if (k == 0 || k == n) {
            return 1;
        }
        return binomialCoeff(n - 1, k - 1) + binomialCoeff(n - 1, k);
    }

    public static long rencontresNumber(int n, int m) {
        if (n == 0 && m == 0) {
            return 1;
        }
        if (n == 1 && m == 0) {
            return 0;
        }
        if (m == 0) {
            return (n - 1) * (rencontresNumber(n - 1, 0) + rencontresNumber(n - 2, 0));
        }
        return binomialCoeff(n, m) * rencontresNumber(n - m, 0);
    }
}

