public class LuckyNumbers {
    public static List<Integer> luckyNum(int n) {
        List<Integer> list = new ArrayList<>();
        for (int i = -1; i < n * n + 9; i += 2) {
            list.add(i);
        }
        int i = 2;
        while (i < list.size()) {
            int step = list.get(i);
            Set<Integer> toRemove = new HashSet<>();
            for (int j = step; j < list.size(); j += step) {
                toRemove.add(list.get(j));
            }
            List<Integer> newList = new ArrayList<>();
            for (Integer num : list) {
                if (!toRemove.contains(num)) {
                    newList.add(num);
                }
            }
            list = newList;
            i++;
        }
        return list.subList(1, Math.min(n + 1, list.size()));
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
        List<Integer> result = luckyNum(n);
        for (Integer num : result) {
            System.out.println(num);
        }
    }
}

public class Solution {
    public static int maxSubarrayProduct(int[] arr) {
        int n = arr.length;
        int maxEndingHere = 1;
        int minEndingHere = 1;
        int maxSoFar = 0;
        int flag = 0;
        for (int i = 0; i < n; i++) {
            if (arr[i] > 0) {
                maxEndingHere *= arr[i];
                minEndingHere = Math.min(minEndingHere * arr[i], 1);
                flag = 1;
            } else if (arr[i] == 0) {
                maxEndingHere = 1;
                minEndingHere = 1;
            } else {
                int temp = maxEndingHere;
                maxEndingHere = Math.max(minEndingHere * arr[i], 1);
                minEndingHere = temp * arr[i];
            }
            if (maxSoFar < maxEndingHere) {
                maxSoFar = maxEndingHere;
            }
        }
        if (flag == 0 && maxSoFar == 0) {
            return 0;
        }
        return maxSoFar;
    }
}

public class Solution {
    public static long sumofFactors(long n) {
        if (n % 2 != 0) {
            return 0;
        }
        long res = 1;
        long tempN = n;
        long limit = (long) Math.sqrt(n) + 1;
        for (long i = 2; i <= limit; i++) {
            long count = 0;
            long curr_sum = 1;
            long curr_term = 1;
            while (tempN % i == 0) {
                count++;
                tempN /= i;
                if (i == 2 && count == 1) {
                    curr_sum = 0;
                }
                curr_term *= i;
                curr_sum += curr_term;
            }
            res *= curr_sum;
        }
        if (tempN >= 2) {
            res *= (1 + tempN);
        }
        return res;
    }
}

