public class Solution {
    public static int lps(String str) {
        int n = str.length();
        int[][] L = new int[n][n];
        for (int i = 0; i < n; i++) {
            L[i][i] = 1;
        }
        for (int cl = 2; cl <= n; cl++) {
            for (int i = 0; i <= n - cl; i++) {
                int j = i + cl - 1;
                if (str.charAt(i) == str.charAt(j) && cl == 2) {
                    L[i][j] = 2;
                } else if (str.charAt(i) == str.charAt(j)) {
                    L[i][j] = L[i + 1][j - 1] + 2;
                } else {
                    L[i][j] = Math.max(L[i][j - 1], L[i + 1][j]);
                }
            }
        }
        return L[0][n - 1];
    }
}

public class MaxSumIncreasingSubseq {
    public static int maxSumIncreasingSubseq(int[] a, int n, int index, int k) {
        int[][] dp = new int[n][n];
        for (int i = 0; i < n; i++) {
            if (a[i] > a[0]) {
                dp[0][i] = a[i] + a[0];
            } else {
                dp[0][i] = a[i];
            }
        }
        for (int i = 1; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (a[j] > a[i] && j > i) {
                    dp[i][j] = Math.max(dp[i - 1][i] + a[j], dp[i - 1][j]);
                } else {
                    dp[i][j] = dp[i - 1][j];
                }
            }
        }
        return dp[index][k];
    }
}

public class RotationCounter {
    public static int findRotationCount(int[] A) {
        int left = 0;
        int right = A.length - 1;
        while (left <= right) {
            if (A[left] <= A[right]) {
                return left;
            }
            int mid = left + (right - left) / 2;
            int next = (mid + 1) % A.length;
            int prev = (mid - 1 + A.length) % A.length;
            if (A[mid] <= A[next] && A[mid] <= A[prev]) {
                return mid;
            } else if (A[mid] <= A[right]) {
                right = mid - 1;
            } else if (A[mid] >= A[left]) {
                left = mid + 1;
            }
        }
        return -1;
    }
}

