public class Solution {
    public static int maximumSegments(int n, int a, int b, int c) {
        int[] dp = new int[n + 10];
        Arrays.fill(dp, -1);
        dp[0] = 0;
        for (int i = 0; i < n; i++) {
            if (dp[i] != -1) {
                if (i + a <= n) {
                    dp[i + a] = Math.max(dp[i] + 1, dp[i + a]);
                }
                if (i + b <= n) {
                    dp[i + b] = Math.max(dp[i] + 1, dp[i + b]);
                }
                if (i + c <= n) {
                    dp[i + c] = Math.max(dp[i] + 1, dp[i + c]);
                }
            }
        }
        return dp[n];
    }
}

public class CountingSort {
    public static int[] countingSort(int[] myList) {
        int maxValue = 0;
        for (int i = 0; i < myList.length; i++) {
            if (myList[i] > maxValue) {
                maxValue = myList[i];
            }
        }
        int[] buckets = new int[maxValue + 1];
        for (int num : myList) {
            buckets[num]++;
        }
        int index = 0;
        for (int j = 0; j <= maxValue; j++) {
            for (int count = 0; count < buckets[j]; count++) {
                myList[index++] = j;
            }
        }
        return myList;
    }
}

