public class CoinChange {
    public static int minCoins(int[] coins, int m, int V) {
        if (V == 0) {
            return 0;
        }
        int res = Integer.MAX_VALUE;
        for (int i = 0; i < m; i++) {
            if (coins[i] <= V) {
                int subRes = minCoins(coins, m, V - coins[i]);
                if (subRes != Integer.MAX_VALUE && subRes + 1 < res) {
                    res = subRes + 1;
                }
            }
        }
        return res;
    }
}

public class CoinChange {
    public static int coinChange(int[] S, int m, int n) {
        int[][] table = new int[n + 1][m];
        for (int i = 0; i < m; i++) {
            table[0][i] = 1;
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < m; j++) {
                int x = (i - S[j] >= 0) ? table[i - S[j]][j] : 0;
                int y = (j >= 1) ? table[i][j - 1] : 0;
                table[i][j] = x + y;
            }
        }
        return table[n][m - 1];
    }
}

public class MinHeapChecker {
    public static boolean checkMinHeap(int[] arr, int i) {
        if (2 * i + 2 > arr.length) {
            return true;
        }
        boolean leftChild = arr[i] <= arr[2 * i + 1] && checkMinHeap(arr, 2 * i + 1);
        boolean rightChild = 2 * i + 2 == arr.length || (arr[i] <= arr[2 * i + 2] && checkMinHeap(arr, 2 * i + 2));
        return leftChild && rightChild;
    }
}

import java.util.*;

public class Solution {
    static class Node implements Comparable<Node> {
        int value, listNum, index;
        Node(int value, int listNum, int index) {
            this.value = value;
            this.listNum = listNum;
            this.index = index;
        }
        @Override
        public int compareTo(Node other) {
            return Integer.compare(this.value, other.value);
        }
    }

    public static int[] findMinimumRange(List<List<Integer>> lists) {
        int high = Integer.MIN_VALUE;
        int[] range = {0, Integer.MAX_VALUE};
        PriorityQueue<Node> pq = new PriorityQueue<>();
        for (int i = 0; i < lists.size(); i++) {
            int val = lists.get(i).get(0);
            pq.offer(new Node(val, i, 0));
            high = Math.max(high, val);
        }
        while (true) {
            Node top = pq.poll();
            int low = top.value;
            int i = top.listNum;
            int j = top.index;
            if (high - low < range[1] - range[0]) {
                range[0] = low;
                range[1] = high;
            }
            if (j == lists.get(i).size() - 1) {
                return range;
            }
            int newVal = lists.get(i).get(j + 1);
            pq.offer(new Node(newVal, i, j + 1));
            high = Math.max(high, newVal);
        }
    }
}

