public class PancakeSort {
    public static int[] pancakeSort(int[] nums) {
        int n = nums.length;
        for (int currSize = n; currSize > 1; currSize--) {
            int maxIndex = 0;
            for (int i = 1; i < currSize; i++) {
                if (nums[i] > nums[maxIndex]) {
                    maxIndex = i;
                }
            }
            flip(nums, 0, maxIndex);
            flip(nums, 0, currSize - 1);
        }
        return nums;
    }

    private static void flip(int[] nums, int start, int end) {
        while (start < end) {
            int temp = nums[start];
            nums[start] = nums[end];
            nums[end] = temp;
            start++;
            end--;
        }
    }
}

public class Statistics {
    public static double sdCalc(double[] data) {
        int n = data.length;
        if (n <= 1) {
            return 0.0;
        }
        double mean = avgCalc(data);
        double sd = 0.0;
        for (double el : data) {
            sd += Math.pow(el - mean, 2);
        }
        return Math.sqrt(sd / (n - 1));
    }

    public static double avgCalc(double[] data) {
        int n = data.length;
        if (n <= 1) {
            return data[0];
        }
        double sum = 0.0;
        for (double el : data) {
            sum += el;
        }
        return sum / n;
    }
}

public class Main {
    public static long sumOfOddFactors(long n) {
        long res = 1;
        while (n % 2 == 0) {
            n /= 2;
        }
        long limit = (long) Math.sqrt(n) + 1;
        for (long i = 3; i <= limit; i += 2) {
            long count = 0;
            long currSum = 1;
            long currTerm = 1;
            while (n % i == 0) {
                count++;
                n /= i;
                currTerm *= i;
                currSum += currTerm;
            }
            res *= currSum;
        }
        if (n >= 2) {
            res *= (1 + n);
        }
        return res;
    }
}

