public class GCD {
    public static int gcd(int x, int y) {
        int gcd = 1;
        if (x % y == 0) {
            return y;
        }
        for (int k = y / 2; k > 0; k--) {
            if (x % k == 0 && y % k == 0) {
                gcd = k;
                break;
            }
        }
        return gcd;
    }
}

public class Solution {
    public static int noOfSubsequences(int[] arr, int k) {
        int n = arr.length;
        int[][] dp = new int[k + 1][n + 1];
        for (int i = 1; i <= k; i++) {
            for (int j = 1; j <= n; j++) {
                dp[i][j] = dp[i][j - 1];
                if (arr[j - 1] <= i && arr[j - 1] > 0) {
                    dp[i][j] += dp[i / arr[j - 1]][j - 1] + 1;
                }
            }
        }
        return dp[k][n];
    }
}

