public class LCMCalculator {
    public static int findLcm(int num1, int num2) {
        int num, den;
        if (num1 > num2) {
            num = num1;
            den = num2;
        } else {
            num = num2;
            den = num1;
        }
        int rem = num % den;
        while (rem != 0) {
            num = den;
            den = rem;
            rem = num % den;
        }
        int gcd = den;
        return (num1 * num2) / gcd;
    }

