public class Solution {
    public int maximumProduct(int[] nums) {
        PriorityQueue<Integer> largest = new PriorityQueue<>();
        PriorityQueue<Integer> smallest = new PriorityQueue<>(Collections.reverseOrder());
        for (int n : nums) {
            largest.offer(n);
            if (largest.size() > 3) {
                largest.poll();
            }
            smallest.offer(n);
            if (smallest.size() > 2) {
                smallest.poll();
            }
        }
        int third = largest.poll();
        int second = largest.poll();
        int first = largest.poll();
        int secondSmallest = smallest.poll();
        int smallestNum = smallest.poll();
        return Math.max(first * second * third, first * smallestNum * secondSmallest);
    }
}

public class SortByDNF {
    public static int[] sortByDNF(int[] arr) {
        int low = 0, mid = 0, high = arr.length - 1;
        while (mid <= high) {
            if (arr[mid] == 0) {
                int temp = arr[low];
                arr[low] = arr[mid];
                arr[mid] = temp;
                low++;
                mid++;
            } else if (arr[mid] == 1) {
                mid++;
            } else {
                int temp = arr[mid];
                arr[mid] = arr[high];
                arr[high] = temp;
                high--;
            }
        }
        return arr;
    }
}

