        List<Integer> ludics = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            ludics.add(i);
        }
        int index = 1;
        while (index != ludics.size()) {
            int firstLudic = ludics.get(index);
            int removeIndex = index + firstLudic;
            while (removeIndex < ludics.size()) {
                ludics.remove(removeIndex);
