        }
        Iterator<List<T>> iterator = nestedList.iterator();
        Set<T> resultSet = new HashSet<>(iterator.next());
        while (iterator.hasNext()) {
            resultSet.retainAll(iterator.next());
        }
        return new ArrayList<>(resultSet);
    }
}

