public class OddDaysCalculator {
    public static int oddDays(int N) {
        int hund1 = N / 100;
        int hund4 = N / 400;
        int leap = N / 4;
        int ordd = N - leap;
        if (hund1 != 0) {
            ordd += hund1;
            leap -= hund1;
        }
        if (hund4 != 0) {
            ordd -= hund4;
            leap += hund4;
        }
        int days = ordd + leap * 2;
        return days % 7;
    }
}

public class ArmstrongNumberChecker {
    public static boolean isArmstrong(int number) {
        int sum = 0;
        int digits = 0;
        int temp = number;
        while (temp > 0) {
            digits++;
            temp /= 10;
        }
        temp = number;
        while (temp > 0) {
            int remainder = temp % 10;
            sum += (int) Math.pow(remainder, digits);
            temp /= 10;
        }
        return number == sum;
    }
}

