public class Solution {
    public static long countWays(int n) {
        long[] A = new long[n + 1];
        long[] B = new long[n + 1];
        A[0] = 1;
        if (n >= 1) {
            A[1] = 0;
            B[0] = 0;
            B[1] = 1;
        }
        for (int i = 2; i <= n; i++) {
            A[i] = A[i - 2] + 2 * B[i - 1];
            B[i] = A[i - 1] + B[i - 2];
        }
        return A[n];
    }
}

