public class Solution {
    public static long countSubstrings(String s, int n) {
        long count = 0;
        int sum = 0;
        Map<Integer, Integer> mp = new HashMap<>();
        mp.put(0, 1);
        for (int i = 0; i < n; i++) {
            sum += s.charAt(i) - '0';
            int key = sum - (i + 1);
            int freq = mp.getOrDefault(key, 0);
            count += freq;
            mp.put(key, freq + 1);
        }
        return count;
    }
}

public class ToggleBits {
    public static int takeLAndFSetBits(int n) {
        n = n | (n >> 1);
        n = n | (n >> 2);
        n = n | (n >> 4);
        n = n | (n >> 8);
        n = n | (n >> 16);
        return ((n + 1) >> 1) + 1;
    }

    public static int toggleFAndLBits(int n) {
        if (n == 1) {
            return 0;
        }
        return n ^ takeLAndFSetBits(n);
    }
}

public class BitToggler {
    private static int setMiddleBits(int n) {
        n |= n >> 1;
        n |= n >> 2;
        n |= n >> 4;
        n |= n >> 8;
        n |= n >> 16;
        return (n >> 1) ^ 1;
    }

    public static int toggleMiddleBits(int n) {
        if (n == 1) {
            return 1;
        }
        return n ^ setMiddleBits(n);
    }
}

public class OctalConverter {
    public static int octalToDecimal(int n) {
        int num = n;
        int decValue = 0;
        int base = 1;
        int temp = num;
        while (temp != 0) {
            int lastDigit = temp % 10;
            temp = temp / 10;
            decValue += lastDigit * base;
            base *= 8;
        }
        return decValue;
    }
}

