public class DecimalToBinary {
    public static long decimalToBinary(int N) {
        long bNumber = 0;
        int cnt = 0;
        while (N != 0) {
            int rem = N % 2;
            long c = (long)Math.pow(10, cnt);
            bNumber += rem * c;
            N /= 2;
            cnt++;
        }
        return bNumber;
    }
}

public class DecimalToOctal {
    public static int decimalToOctal(int deciNum) {
        int octalNum = 0;
        int countval = 1;
        int dNo = deciNum;
        while (deciNum != 0) {
            int remainder = deciNum % 8;
            octalNum += remainder * countval;
            countval *= 10;
            deciNum /= 8;
        }
        return octalNum;
    }
}

