public class JacobsthalLucas {
    public static int jacobsthalLucas(int n) {
        int[] dp = new int[n + 1];
        dp[0] = 2;
        dp[1] = 1;
        for (int i = 2; i <= n; i++) {
            dp[i] = dp[i - 1] + 2 * dp[i - 2];
        }
        return dp[n];
    }
}

